create extension if not exists pg_trgm with schema extensions;
create table public.records (id text primary key check (id ~ '^[a-f0-9]{8}$'), modality text not null check (modality in ('FLL','OBR')), status text not null default 'pending' check (status in ('pending','published','deleting')), record_date date not null, title text not null check (char_length(title) between 3 and 140), summary text not null default '', slug text not null, folder_path text not null unique, json_path text not null, cover_path text, cover_thumb_path text, tags text[] not null default '{}', author_name text not null default '', image_count int not null default 0, video_count int not null default 0, search_text text not null default '', doc_version int not null default 1, idempotency_key text, created_at timestamptz not null default now(), updated_at timestamptz not null default now(), published_at timestamptz, search_tsv tsvector generated always as (to_tsvector('portuguese',coalesce(search_text,''))) stored);
create index records_cal_idx on public.records (modality,record_date desc,created_at desc) where status='published';
create index records_status_idx on public.records (status,created_at); create index records_tags_idx on public.records using gin(tags); create index records_tsv_idx on public.records using gin(search_tsv); create index records_trgm_idx on public.records using gin(search_text extensions.gin_trgm_ops); create unique index records_idem_idx on public.records(idempotency_key) where idempotency_key is not null;
create table public.audit_logs (id bigint generated always as identity primary key, at timestamptz not null default now(), action text not null check(action in ('create','update','delete','import','export','cleanup')), record_id text, modality text, title text, actor text, details jsonb not null default '{}'::jsonb);
create index audit_logs_at_idx on public.audit_logs(at desc); alter table public.records enable row level security; alter table public.audit_logs enable row level security;
